package com.bank.workflow;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class GenerateParenthesesDemo {

    private static final Logger log = Logger.getLogger(GenerateParenthesesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        WorkflowShapeGenerator generator = new WorkflowShapeGenerator();

        int pairs = 3;
        List<String> shapes = generator.generate(pairs);
        log.info(() -> "Valid shapes for " + pairs + " pairs: " + shapes.size()); // 5
        shapes.forEach(s -> log.info(() -> "  shape: " + s));
    }
}

