class WorkflowShapeGenerator {

    private static final Logger log = Logger.getLogger(WorkflowShapeGenerator.class.getName());

    java.util.List<String> generate(int n) {
        java.util.List<String> result = new java.util.ArrayList<>();
        backtrack(new StringBuilder(), 0, 0, n, result);
        return result;
    }

    private void backtrack(StringBuilder sb, int open, int close, int n,
                           java.util.List<String> result) {
        if (sb.length() == 2 * n) {           // used all n openers and n closers
            result.add(sb.toString());
            return;
        }
        if (open < n) {                       // budget left for an opener
            sb.append('(');
            backtrack(sb, open + 1, close, n, result);
            sb.deleteCharAt(sb.length() - 1); // undo
        }
        if (close < open) {                   // only close something already open
            sb.append(')');
            backtrack(sb, open, close + 1, n, result);
            sb.deleteCharAt(sb.length() - 1); // undo
        }
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
